(() => {
    switch (field.type) {
      case 'text':
        return (
          <input
            id={id}
            type="text"
            value={typeof value === 'string' ? value : ''}
            aria-describedby={help}
            onChange={(event) => onChange(event.target.value)}
            className={FIELD}
          />
        )
      case 'textarea':
        return (
          <textarea
            id={id}
            rows={3}
            value={typeof value === 'string' ? value : ''}
            aria-describedby={help}
            onChange={(event) => onChange(event.target.value)}
            className={`${FIELD} resize-y`}
          />
        )
      case 'select':
        return (
          <select
            id={id}
            value={typeof value === 'string' ? value : ''}
            aria-describedby={help}
            onChange={(event) => onChange(event.target.value)}
            className={FIELD}
          >
            {field.options.map((option) => (
              <option key={option} value={option}>
                {option}
              </option>
            ))}
          </select>
        )
      case 'toggle':
        return (
          <input
            id={id}
            type="checkbox"
            checked={value === true}
            aria-describedby={help}
            onChange={(event) => onChange(event.target.checked)}
            className="h-4 w-4 accent-accent"
          />
        )
      case 'color':
        return (
          <div className="flex items-center gap-2">
            <input
              id={id}
              type="color"
              value={typeof value === 'string' ? value : '#000000'}
              aria-describedby={help}
              onChange={(event) => onChange(event.target.value)}
              className="h-7 w-10 rounded border border-content-muted/30 bg-surface"
            />
            <span className="font-mono text-xs text-content-muted">{typeof value === 'string' ? value : ''}</span>
          </div>
        )
      case 'range':
        return (
          <div className="flex items-center gap-2">
            <input
              id={id}
              type="range"
              min={field.min}
              max={field.max}
              step={field.step ?? 1}
              value={typeof value === 'number' ? value : field.min}
              aria-describedby={help}
              onChange={(event) => onChange(Number(event.target.value))}
              className="min-w-0 flex-1 accent-accent"
            />
            <output htmlFor={id} className="w-10 text-right font-mono text-xs">
              {typeof value === 'number' ? value : ''}
            </output>
          </div>
        )
    }
  })
